//! Public authoritative held/choice/queue tests with independently controlled completion draws.
use gielinor_world::{grinding,tool_crafting::{Recipe,Failure,Request},held_use::{Handler,Scope,Type,Request as Held},inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,npc::RandomSource,CoordGrid};
use std::{sync::Arc,collections::VecDeque};
struct Draw{values:VecDeque<u32>,calls:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,256);self.calls+=1;self.values.pop_front().expect("unexpected draw after captured work stopped")}}
fn profile(i:usize)->Recipe{let(raw,out,broken)=[(7538,7539,7541),(7536,7537,7540)][i];let(level,xp,fail,low,high,seq)=(15,325,0,40,240,1280);Recipe{exchange:grinding::Recipe{tool:1755,input:raw,output:out,members:true,animation:Some(seq)},level,xp_tenths:xp,ticks:3,name:"independent crab",action:"carve",failure:Some(Failure{output:broken,xp_tenths:fail,low,high,message:"You accidentally break the crab material."})}}
fn fixture(i:usize,reverse:bool)->(World,ActorId,Request,Held){let r=profile(i);let mut w=World::default();w.collision.allocate(3200,3200,0);let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut d=PlayerData::new(1,"Independent fallible queue".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;
 for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for(s,id)in[(0,1755),(1,1755),(3,r.exchange.input),(9,r.exchange.input),(17,r.exchange.input),(26,r.exchange.input)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}
 w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[1755,r.exchange.input]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1755,r.exchange.input,Handler::ToolCraftingChoices{recipes:Arc::new(vec![r]),cycle_ticks:3}).unwrap();let held=if reverse{Held{selected_slot:17,selected_id:r.exchange.input,target_slot:0,target_id:1755}}else{Held{selected_slot:0,selected_id:1755,target_slot:17,target_id:r.exchange.input}};w.prepare_held_use(a,held).unwrap();w.finish_held_use(a,held).unwrap();let q=w.take_tool_crafting_request(a).unwrap().unwrap();w.drain_events();(w,a,q,held)}
#[test]
fn forty_eight_mixed_and_uniform_batches_preserve_every_slot_reward_and_exact_draw_clock(){let mut cases=0;for i in 0..2{for reverse in[false,true]{for rate in[100,125,500]{for rolls in[[0,255,0],[255,0,255],[0,0,0],[255,255,255]]{
 let(mut w,a,q,held)=fixture(i,reverse);w.data_mut(a).unwrap().xp_rate_hundreds=rate;let initial=w.data(a).unwrap().clone();let mut expected=initial.inventory.clone();let mut stats=initial.stats.clone();let start=w.clock.0;let r=profile(i);let mut rng=Draw{values:rolls.into(),calls:0};w.start_tool_crafting_choice(a,q,0,3).unwrap();assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(rng.calls,0);let mut seen=0;
 for _ in 0..14{w.tick_with_random(&mut rng).unwrap();if rng.calls!=seen{assert_eq!(rng.calls,seen+1);assert_eq!(w.clock.0-start,4+3*seen as i32);let good=rolls[seen]==0;let slot=[17,3,9][seen];expected.restore_slot(slot,Some(Item{id:if good{r.exchange.output}else{r.failure.unwrap().output},count:1,vars:0})).unwrap();stats.set_fine_xp(12,stats.fine_xp(12)+(if good{r.xp_tenths}else{r.failure.unwrap().xp_tenths}) as i32*rate/100).unwrap();seen+=1;}assert_eq!(w.data(a).unwrap().inventory,expected,"profile{i} draws{seen}");assert_eq!(w.data(a).unwrap().stats,stats);}
 assert_eq!(rng.calls,3);assert_eq!(w.drain_events().iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{..})).count(),rolls.iter().filter(|v|**v==0).count());assert_eq!(expected.free_space(),0);assert_eq!(expected.get(26).unwrap().id,r.exchange.input);assert!(w.finish_held_use(a,held).is_err());for _ in 0..8{w.tick_with_random(&mut rng).unwrap();}assert_eq!(rng.calls,3);assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,stats);cases+=1;
 }}}}assert_eq!(cases,48);}
#[test]
fn fifty_six_late_changes_stop_before_a_second_draw_without_fallback(){let mut cases=0;for i in 0..2{for reverse in[false,true]{for mode in 0..14{let(mut w,a,q,_)=fixture(i,reverse);let r=profile(i);let mut rng=Draw{values:[0].into(),calls:0};w.start_tool_crafting_choice(a,q,0,3).unwrap();for _ in 0..3{w.tick_with_random(&mut rng).unwrap();assert_eq!(rng.calls,0);}w.tick_with_random(&mut rng).unwrap();assert_eq!(rng.calls,1);assert_eq!(w.data(a).unwrap().inventory.get(17).unwrap().id,r.exchange.output);
 match mode{0=>{w.data_mut(a).unwrap().inventory.restore_slot(3,Some(Item{id:1931,count:1,vars:0})).unwrap();w.data_mut(a).unwrap().inventory.restore_slot(25,Some(Item{id:r.exchange.input,count:1,vars:0})).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(3,Some(Item{id:r.exchange.input,count:1,vars:1})).unwrap();},2=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},3=>w.set_membership(a,false).unwrap(),4=>w.data_mut(a).unwrap().stats.set_current(12,r.level as i8-1),5=>w.data_mut(a).unwrap().xp_rate_hundreds=0,6=>{w.object_types.dummy.insert(r.exchange.output);},7=>{w.object_types.dummy.insert(r.failure.unwrap().output);},8=>{w.set_modal_open(a,true).unwrap();w.set_modal_open(a,false).unwrap();},9=>w.submit(a,Action::Walk{destination:CoordGrid::new(3201,3200,0).unwrap(),run:false}).unwrap(),10=>w.request_logout(a).unwrap(),11=>{w.close_dialogs(a).unwrap();},12=>{let h=Held{selected_slot:0,selected_id:1755,target_slot:26,target_id:r.exchange.input};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();assert!(w.take_tool_crafting_request(a).unwrap().is_some());},_=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:1755,count:1,vars:1})).unwrap();}}
 let before=w.data(a).unwrap().clone();for _ in 0..14{w.tick_with_random(&mut rng).unwrap();}assert_eq!(rng.calls,1);assert_eq!(w.data(a).unwrap().inventory,before.inventory,"profile{i} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);cases+=1;
 }}}assert_eq!(cases,56);}
#[test]
fn fifty_six_invalid_admissions_never_roll_or_publish(){let mut cases=0;for i in 0..2{for reverse in[false,true]{for mode in 0..14{let(mut w,a,q,_)=fixture(i,reverse);let r=profile(i);match mode{3=>w.data_mut(a).unwrap().stats.set_current(12,r.level as i8-1),4=>w.set_membership(a,false).unwrap(),5=>w.data_mut(a).unwrap().xp_rate_hundreds=0,6=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},7=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:r.exchange.input,count:1,vars:1})).unwrap();},8=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},9=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:1755,count:1,vars:1})).unwrap();},10=>{w.object_types.dummy.insert(r.exchange.output);},11=>{w.object_types.dummy.insert(r.failure.unwrap().output);},12=>w.set_modal_open(a,true).unwrap(),13=>w.request_logout(a).unwrap(),_=>{}}
 let before=w.data(a).unwrap().clone();let result=w.start_tool_crafting_choice(a,q,if mode==0{1}else{0},if mode==1{0}else if mode==2{29}else{3});if matches!(mode,0|1|2|12|13){assert!(result.is_err(),"mode{mode}");}let mut rng=Draw{values:VecDeque::new(),calls:0};for _ in 0..14{w.tick_with_random(&mut rng).unwrap();}assert_eq!(rng.calls,0);assert_eq!(w.data(a).unwrap().inventory,before.inventory,"profile{i} mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats);cases+=1;
 }}}assert_eq!(cases,56);}
